#include <stdio.h>
#include <string.h>

int main() {
    char word[] = "malayalam";
    int len = strlen(word);

    /* Reverse into a new string */
    char rev[20];
    for (int i = 0; i < len; i++) {
        rev[i] = word[len - 1 - i];
    }
    rev[len] = '\0';
    printf("Reversed: %s\n", rev);

    /* Palindrome check */
    if (strcmp(word, rev) == 0) {
        printf("%s is a palindrome\n", word);
    } else {
        printf("%s is not a palindrome\n", word);
    }

    /* Count vowels */
    int vowels = 0;
    for (int i = 0; word[i] != '\0'; i++) {
        char c = word[i];
        if (c == 'a' || c == 'e' || c == 'i' || c == 'o' || c == 'u') {
            vowels++;
        }
    }
    printf("Vowels: %d\n", vowels);
    return 0;
}

